      "content": "import { NextRequest, NextResponse } from 'next/server';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { z } from 'zod';

const schema = z.object({ email: z.string().email(), password: z.string().min(6) });

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const parsed = schema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json({ error: 'validation_error', message: 'Invalid credentials format' }, { status: 400 });
    }
    const user = { id: 'demo-user', email: 'demo@example.com', passwordHash: await bcrypt.hash('password123', 10) };
    if (parsed.data.email !== user.email) {
      return NextResponse.json({ error: 'auth_error', message: 'Invalid email or password' }, { status: 401 });
    }
    const ok = await bcrypt.compare(parsed.data.password, user.passwordHash);
    if (!ok) {
      return NextResponse.json({ error: 'auth_error', message: 'Invalid email or password' }, { status: 401 });
    }
    const token = jwt.sign({ sub: user.id, email: user.email }, process.env.JWT_SECRET || 'dev-secret', { expiresIn: '1h' });
    return NextResponse.json({ token, user: { id: user.id, email: user.email } }, { status: 200 });
  } catch {
    return NextResponse.json({ error: 'server_error', message: 'Unable to process login' }, { status: 500 });
  }
}
